class_basic.source:
# Class: 定义与调用 (含 staticmethod / classmethod)

class MyClass:
    class_var = 100

    def __init__(self, val):
        self.val = val

    @classmethod
    def get_class_var(cls):
        return cls.class_var

    @classmethod
    def increment_class_var(cls):
        cls.class_var = cls.class_var + 1

    @classmethod
    def factory(cls, x):
        return cls(x)

    @staticmethod
    def add(a, b):
        return a + b

    @staticmethod
    def greet(name):
        return "Hello, " + name

    def get_val(self):
        return self.val


# 通过类调用 classmethod
print("classmethod on class:", MyClass.get_class_var())  # 100

# 通过实例调用 classmethod
obj = MyClass(42)
print("classmethod on instance:", obj.get_class_var())  # 100

# classmethod 工厂方法
obj2 = MyClass.factory(99)
print("factory:", obj2.get_val())  # 99

# 通过类调用 staticmethod
print("staticmethod on class:", MyClass.add(3, 7))  # 10

# 通过实例调用 staticmethod
print("staticmethod on instance:", obj.add(10, 20))  # 30

# staticmethod 字符串操作
print("staticmethod greet:", MyClass.greet("World"))  # Hello, World
print("staticmethod greet instance:", obj.greet("DSL"))  # Hello, DSL

# 综合调用测试
print("class_var:", MyClass.class_var)  # 100
MyClass.increment_class_var()
print("class_var:", MyClass.get_class_var())  # 101
MyClass.increment_class_var()
obj.increment_class_var()
print("class_var:", MyClass.class_var)  # 103
MyClass.increment_class_var()
print("class_var:", MyClass.get_class_var())  # 104

class_inherit.source:
# Class: 继承


class Animal:
    sound = "generic"

    @classmethod
    def make_sound(cls):
        return cls.sound

    @staticmethod
    def info():
        return "I am an animal"


class Dog(Animal):
    sound = "woof"

    @staticmethod
    def info():
        return "I am a dog"


class Cat(Animal):
    sound = "meow"


print("Animal sound:", Animal.make_sound())  # generic
print("Dog sound:", Dog.make_sound())  # woof
print("Cat sound:", Cat.make_sound())  # meow

# staticmethod 也可以被子类 override
print("Animal info:", Animal.info())  # I am an animal
print("Dog info:", Dog.info())  # I am a dog
print("Cat info:", Cat.info())  # I am an animal (继承)

