edge_property.source:
# Edge: @property 装饰器

class Circle:
    def __init__(self, radius):
        self._radius = radius

    @property
    def radius(self):
        return self._radius

    @radius.setter
    def radius(self, value):
        if value < 0:
            raise ValueError("radius must be non-negative")
        self._radius = value

    @property
    def area(self):
        return 3.14159 * self._radius * self._radius

c = Circle(5)
print(c.radius)              # 5
print(c.area)                # ~78.53975

c.radius = 10
print(c.radius)              # 10
print(c.area)                # ~314.159

# @property 只读
class ReadOnly:
    def __init__(self, v):
        self._v = v

    @property
    def v(self):
        return self._v

ro = ReadOnly(42)
print(ro.v)                  # 42
try:
    ro.v = 100
except AttributeError:
    print("AttributeError")  # AttributeError

print("done")

edge_protocols.source:
# Edge: __len__ / __contains__ / __iter__ / __next__

# __len__
class MyCollection:
    def __init__(self, items):
        self.items = items
    def __len__(self):
        return len(self.items)
    def __contains__(self, item):
        return item in self.items
    def __iter__(self):
        return iter(self.items)

mc = MyCollection([1, 2, 3, 4, 5])
print(len(mc))               # 5
print(3 in mc)               # True
print(6 in mc)               # False

for item in mc:
    print(item, end=" ")     # 1 2 3 4 5
print()

# 转列表
print(list(mc))              # [1, 2, 3, 4, 5]

print("done")

edge_recursion.source:
# Edge: 递归深度

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

print(factorial(5))           # 120
print(factorial(10))          # 3628800

# 相互递归
def is_even(n):
    if n == 0:
        return True
    return is_odd(n - 1)

def is_odd(n):
    if n == 0:
        return False
    return is_even(n - 1)

print(is_even(10))            # True
print(is_even(11))            # False
print(is_odd(10))             # False
print(is_odd(11))             # True

print("done")

